#!/bin/bash
set -eo pipefail
task_root='/data1/home/sunyiq/us_nonnegative_repair_execution_20261010_001/audit_cpu_v2'
test "$(id -un)" = sunyiq
test "$(readlink -e /data1/home/sunyiq/us_nonnegative_repair_execution_20261010_001)" = /data1/home/sunyiq/us_nonnegative_repair_execution_20261010_001
test ! -e "$task_root"
test ! -L "$task_root"
mkdir "$task_root"
mkdir "$task_root/logs"
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B -X utf8 - <<'OWN_BOUND_AUDIT_CPU_DEPLOY_PY'
import json,base64,hashlib,os,stat
from pathlib import Path
root=Path('/data1/home/sunyiq/us_nonnegative_repair_execution_20261010_001/audit_cpu_v2')
assert root.is_absolute() and root.resolve(strict=True)==root
payload=base64.b64decode('',validate=True)
assert hashlib.sha256(payload).hexdigest()=='0140e513011f581b2895c435f025970193939fca1ac98267744d118265fdfcae'
items=json.loads(payload)
assert len(items)==3 and {x['name'] for x in items}=={'independent_saved_six_rescore_cpu_v2.py','SAVED_SIX_RESCORE_BINDINGS_v1.json','audit_cpu_v2.sbatch'}
for item in items:
 raw=base64.b64decode(item['base64'],validate=True)
 assert len(raw)==item['bytes'] and hashlib.sha256(raw).hexdigest()==item['sha256']
 with (root/item['name']).open('xb') as f: f.write(raw)
print('OWN_SIX_CPU_AUDIT_BOUND_FILES=3')
OWN_BOUND_AUDIT_CPU_DEPLOY_PY
test ! -e "$task_root/SUBMISSION_STARTED.txt"
printf 'ONE_CPU_AUDIT_ONLY_NO_TRAINING\n' > "$task_root/SUBMISSION_STARTED.txt"
set +e
task_submit_output=$(sbatch "$task_root/audit_cpu_v2.sbatch" 2>&1)
task_submit_exit=$?
set -e
printf '%s\nOWN_SIX_CPU_AUDIT_SUBMIT_EXIT=%s\n' "$task_submit_output" "$task_submit_exit"
printf '%s\n' "$task_submit_output" > "$task_root/SUBMISSION_OUTPUT.txt"
test "$task_submit_exit" -eq 0
if [[ "$task_submit_output" =~ ^Submitted\ batch\ job\ ([0-9]+)$ ]]; then
  task_job="${BASH_REMATCH[1]}"
else
  printf 'OWN_SIX_CPU_AUDIT_SUBMISSION_ID_UNCERTAIN_NO_RETRY\n'
  exit 1
fi
printf '%s\n' "$task_job" > "$task_root/OWN_INDEPENDENT_CPU_JOB_ID.txt"
printf 'OWN_SIX_CPU_AUDIT_JOB_ID=%s\n' "$task_job"
squeue -j "$task_job" -h -o '%i|%j|%T|%R' || true
printf 'OWN_SIX_CPU_AUDIT_DEPLOY_DONE\n'
